"package core.generation;

import core.cfg.Coverage;
import org.eclipse.jdt.core.dom.CompilationUnit;
import org.eclipse.jdt.core.dom.MethodDeclaration;

import java.nio.file.Path;
import java.util.List;
import java.util.Map;

public class BatchRunner {

    public static void runAll(Path zipPath, Coverage coverage, int runsPerMethod) {
        System.out.println("Loading project from " + zipPath);
        Project project = new Project(zipPath);
        List<MethodDeclaration> methods = project.getMethods();
        System.out.println("Found " + methods.size() + " methods.");

        int count = 1;
        for (MethodDeclaration method : methods) {
            String methodName = method.getName().getIdentifier();
            System.out.println("[" + count + "/" + methods.size() + "] Testing method: " + methodName);

            CompilationUnit cu = project.getRootAST(method);
            if (cu == null) {
                System.err.println("Could not find root AST for " + methodName);
                continue;
            }

            for (int i = 0; i < runsPerMethod; i++) {
                System.out.println("  -> Run " + (i + 1) + " of " + runsPerMethod);
                try {
                    Map<String, Object> randomInput = RandomTestInput.createRandomTestData(method);
                    ConcolicTesting.getInstance().generate(
                            method,
                            cu,
                            coverage,
                            randomInput,
                            new core.testpath.AllPathsFinder()
                    );
                } catch (Exception e) {
                    System.err.println("  -> Error running " + methodName + ": " + e.getMessage());
                    // Just print stack trace and continue. The python script will detect missing runs.
                    e.printStackTrace();
                }
            }
            count++;
        }
    }
}
