"import core.cfg.Coverage;
import core.generation.BatchRunner;

import java.nio.file.Path;
import java.nio.file.Paths;

public class BatchMain {
    public static void main(String[] args) {
        if (args.length < 1) {
            System.err.println("Usage: java BatchMain <path_to_zip> [STATEMENT|BRANCH|MCDC]");
            System.exit(1);
        }

        Path zipPath = Paths.get(args[0]);
        if (!zipPath.toFile().exists()) {
            System.err.println("Zip file not found: " + zipPath);
            System.exit(1);
        }

        Coverage coverage = Coverage.STATEMENT; // default
        if (args.length >= 2) {
            try {
                coverage = Coverage.valueOf(args[1].toUpperCase());
            } catch (IllegalArgumentException e) {
                System.err.println("Invalid coverage type. Using STATEMENT.");
            }
        }

        System.out.println("Starting batch runner on " + zipPath + " with coverage " + coverage);

        // Run 3 times per method as requested
        BatchRunner.runAll(zipPath, coverage, 3);

        System.out.println("Batch testing completed.");
    }
}
